#!/usr/bin/env python3
from pathlib import Path

P = Path('writing/benevolent_outsider_draft_04_method_primitive_1921_1933.md')
s = P.read_text(encoding='utf-8')

old = "In Huizinga’s own methodological writing, 1929 adds a more general formulation. ‘The primitive cultures of the whole world’, he wrote, had become components of modern civilization; yet a history adequate to that civilization still had to answer to critically scientific verification (Huizinga, 1929: 156–168). The wording changes the temporal position of the object. The ‘primitive cultures of the whole world’ were not merely surviving beginnings outside modern history; they had become components of the civilization whose history Huizinga was trying to understand. In the same essay he made the division concrete: religious studies and ethnology could define forms such as myth, consecration, sacred action, contest-play and secret association, while cultural history followed their *werking* in historical events. Service, honour, loyalty and obedience might each be objects of sociology, but their systematic treatment remained insufficient unless cultural history showed their changing operation and form across centuries and countries. Cultural history could learn from ‘de praktische sociologie der Amerikanen’ and from Mauss without becoming subordinate labour for sociology (Huizinga, 1929). *Primitive* could still order difference, but it no longer supplied a self-explanatory outside from which modern history simply began."
new = "Huizinga’s 1929 methodological writings add two related formulations. In ‘Over een definitie van het begrip geschiedenis’, ‘the primitive cultures of the whole world’ had become components of modern civilization; yet a history adequate to that civilization still had to answer to critically scientific verification (Huizinga, 1929: 156–168). The wording changes the temporal position of the object. The ‘primitive cultures of the whole world’ were not merely surviving beginnings outside modern history; they had become components of the civilization whose history Huizinga was trying to understand. A separate essay in the same volume, ‘De taak der cultuurgeschiedenis’, made the division of labour concrete: religious studies and ethnology could define forms such as myth, consecration, sacred action, contest-play and secret association, while cultural history followed their *werking* in historical events. Service, honour, loyalty and obedience might each be objects of sociology, but their systematic treatment remained insufficient unless cultural history showed their changing operation and form across centuries and countries. Cultural history could learn from ‘de praktische sociologie der Amerikanen’ and from Mauss without becoming subordinate labour for sociology (Huizinga, 1929). *Primitive* could still order difference, but it no longer supplied a self-explanatory outside from which modern history simply began."
if s.count(old) != 1:
    raise SystemExit(f'expected exactly one conflated 1929 paragraph, found {s.count(old)}')
s = s.replace(old, new, 1)
P.write_text(s, encoding='utf-8')
print('patched Draft 04: separated the two 1929 methodological texts')
